/* prog49_bst.c – reconstructed from the obfuscated binary */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64          /* same limit used by the original binary */

static long  value[MAX_NODES];
static int   left[MAX_NODES];
static int   right[MAX_NODES];
static int   root = -1;       /* empty tree */
static int   used = 0;        /* number of nodes allocated */
static int   printed = 0;     /* used by the traversal helpers */

/* -------------------------------------------------------------
   Helper that prints a value with a leading space after the first
   element (exactly what the original program does).
   ------------------------------------------------------------- */
static void print_value(long v)
{
    if (printed)
        putchar(' ');
    printf("%ld", v);
    printed = 1;
}

/* -------------------------------------------------------------
   Insert a value into the binary‑search tree.
   The original binary limits the tree to 64 nodes; we keep the
   same limit but silently ignore extra values (the original code
   would simply stop inserting after the limit is reached).
   ------------------------------------------------------------- */
static void bst_insert(long v)
{
    if (used >= MAX_NODES)               /* tree full – nothing more to do */
        return;

    if (root == -1) {                     /* first node becomes the root */
        root = used;
        value[used] = v;
        left[used] = right[used] = -1;
        used++;
        return;
    }

    int cur = root;
    while (1) {
        if (v < value[cur]) {
            if (left[cur] == -1) {        /* insert as left child */
                left[cur] = used;
                value[used] = v;
                left[used] = right[used] = -1;
                used++;
                break;
            }
            cur = left[cur];
        } else {                          /* v >= value[cur] → go right */
            if (right[cur] == -1) {       /* insert as right child */
                right[cur] = used;
                value[used] = v;
                left[used] = right[used] = -1;
                used++;
                break;
            }
            cur = right[cur];
        }
    }
}

/* -------------------------------------------------------------
   Traversal routines – they match the behaviour of the original
   binary (in‑order, pre‑order and post‑order).  Each routine prints
   the values separated by a single space and sets the global
   `printed` flag so that subsequent numbers are preceded by a space.
   ------------------------------------------------------------- */
static void inorder(int node)
{
    if (node == -1)
        return;
    inorder(left[node]);
    print_value(value[node]);
    inorder(right[node]);
}

static void preorder(int node)
{
    if (node == -1)
        return;
    print_value(value[node]);
    preorder(left[node]);
    preorder(right[node]);
}

static void postorder(int node)
{
    if (node == -1)
        return;
    postorder(left[node]);
    postorder(right[node]);
    print_value(value[node]);
}

/* -------------------------------------------------------------
   Main – parses the command line, builds the BST and prints the
   requested traversal.  It reproduces exactly the messages and
   exit codes of the original program.
   ------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* The original binary treats any argc < 2 as an invalid mode. */
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }

    /* Determine the requested traversal mode. */
    enum { MODE_IN, MODE_PRE, MODE_POST, MODE_BAD } mode = MODE_BAD;
    if (strcmp(argv[1], "in") == 0)
        mode = MODE_IN;
    else if (strcmp(argv[1], "pre") == 0)
        mode = MODE_PRE;
    else if (strcmp(argv[1], "post") == 0)
        mode = MODE_POST;
    else {
        puts("INVALID_MODE");
        return 0;
    }

    /* Insert all numeric arguments into the BST. */
    for (int i = 2; i < argc; ++i) {
        long v = strtol(argv[i], NULL, 10);
        bst_insert(v);
    }

    /* If the tree is empty, print the special message. */
    if (root == -1) {
        puts("EMPTY");
        return 0;
    }

    /* Perform the requested traversal. */
    printed = 0;               /* reset spacing flag */
    switch (mode) {
        case MODE_IN:   inorder(root);   break;
        case MODE_PRE:  preorder(root);  break;
        case MODE_POST: postorder(root); break;
        default:        /* never reached */ break;
    }
    putchar('\n');             /* terminate the line */

    return 0;
}
